#!/bin/bash
#
# Generate the consolidated top-level index.ts for the TypeScript SDK.
#
# Each API is generated by openapi-generator into its own package directory
# under sdk/src/<pkg>/ (each with its own index.ts). This script produces a
# single sdk/index.ts that re-exports every API package under a namespace, plus
# the hand-written LWA auth helpers.
#
# Run from the typescript/ directory (the build workflow does), or directly.

# Navigate to the script's directory (typescript/scripts).
cd "$(dirname "$0")"

# Output file lives in the sdk folder.
output_file="../sdk/index.ts"

# Clear or create the output file.
> "$output_file"

# Function to convert a package directory name to an export namespace name.
# Mirrors the JavaScript SDK naming so both SDKs expose the same namespaces.
get_export_name() {
    local dir=$1

    # Remove version suffix (everything from _v<...>).
    local base_name
    base_name=$(echo "$dir" | sed -E 's/_v[0-9]+.*$//')

    # Special handling to avoid duplicate export names (kept in sync with JS).
    if [[ "$dir" == "pricing_v2022_05_01" ]]; then
        echo "PricingSpApi"
        return
    elif [[ "$dir" == "pricing_v0" ]]; then
        echo "Pricing_v0SpApi"
        return
    elif [[ "$dir" == "fulfillmentinbound_v0" ]]; then
        echo "Fulfillmentinbound_v0SpApi"
        return
    elif [[ "$dir" == "fulfillmentinbound_v2024_03_20" ]]; then
        echo "FulfillmentinboundSpApi"
        return
    elif [[ "$dir" == "orders_v0" ]]; then
        echo "OrdersSpApi"
        return
    elif [[ "$dir" == "orders_v2026_01_01" ]]; then
        echo "Orders_v2026SpApi"
        return
    elif [[ "$dir" == "fulfillmentoutbound_v2026_07_04" ]]; then
        echo "Fulfillmentoutbound_v2026SpApi"
        return
    fi

    # Capitalize first letter of each underscore-separated word and drop underscores.
    local export_name
    export_name=$(echo "$base_name" | awk -F'_' '{
        for(i=1; i<=NF; i++) {
            printf "%s", toupper(substr($i,1,1)) substr($i,2)
        }
    }')

    # Add SpApi suffix.
    echo "${export_name}SpApi"
}

# Process each generated API package directory in sdk/src.
if [ -d ../sdk/src ]; then
    for dir in ../sdk/src/*/; do
        # Skip if the glob did not match anything.
        [ -e "$dir" ] || continue

        # Remove trailing slash and path prefix.
        dir=${dir%/}
        dir=${dir##*/}

        # Get export namespace name.
        export_name=$(get_export_name "$dir")

        # Record the first package directory so we can re-export the shared
        # RateLimiter (identical in every package) at the top level.
        if [ -z "${first_pkg:-}" ]; then
            first_pkg="$dir"
        fi

        # Add export line to file.
        echo "export * as $export_name from './src/$dir/index';" >> "$output_file"
    done
fi

# Sort the file alphabetically.
sort "$output_file" -o "$output_file"

# Add hand-written helper exports at the end.
echo "" >> "$output_file"  # Add blank line for readability
echo "export * from './helper/LwaAuthClient';" >> "$output_file"
echo "export * from './helper/ScopeConstants';" >> "$output_file"

# Re-export the shared RateLimiter (and its wrapper/types) at the top level so
# consumers and tests can import them without going through an API namespace.
# The RateLimiter is byte-identical across all generated packages, so any one
# package is a valid source.
if [ -n "${first_pkg:-}" ]; then
    echo "export * from './src/${first_pkg}/RateLimiter';" >> "$output_file"
fi

# Emit a single shared rate-limit integration test at the sdk root, derived
# from the rate_limit_test template. It is byte-identical regardless of API, so
# we generate it once here rather than once per package. The template's
# license partial line is dropped and its RateLimiter import is repointed at the
# consolidated index.
rate_limit_template="../../templates/typescript/rate_limit_test.mustache"
if [ -f "$rate_limit_template" ] && [ -n "${first_pkg:-}" ]; then
    mkdir -p ../sdk/test
    rate_limit_spec="../sdk/test/RateLimitProtection.spec.ts"
    {
        sed -e '/{{>licenseInfo}}/d' \
            -e "s#from '../RateLimiter'#from '../index'#" \
            "$rate_limit_template"
    } > "$rate_limit_spec"
    echo "Generated shared rate limit test at sdk/test/RateLimitProtection.spec.ts"
fi

# Check for duplicate export names.
duplicates=$(sed -n 's/^export \* as \([^ ]*\) .*/\1/p' "$output_file" | sort | uniq -d)

if [ -n "$duplicates" ]; then
    echo "ERROR: Duplicate export names detected in $output_file:" >&2
    echo "$duplicates" >&2
    echo "" >&2
    echo "Conflicting entries:" >&2
    for dup in $duplicates; do
        grep "as $dup " "$output_file" >&2
    done
    exit 1
fi

echo "Generated consolidated index.ts in sdk folder with exports for all APIs and LWA helpers"
